class Solution {
    public int longestChain(int[] values, int step) {
        int best = 0;
        for (int v : values) {
            int length = 1;
            long next = (long) v + step;
            while (contains(values, next)) {
                length++;
                next += step;
            }
            best = Math.max(best, length);
        }
        return best;
    }

    private boolean contains(int[] values, long x) {
        for (int v : values) if (v == x) return true;
        return false;
    }
}

