from bisect import bisect_left

class Solution:
    def longestChain(self, values: List[int], step: int) -> int:
        s = sorted(set(values))
        length = [1] * len(s)
        for i, v in enumerate(s):
            j = bisect_left(s, v - step, 0, i)
            if j < i and s[j] == v - step:
                length[i] = length[j] + 1
        return max(length)

