class Solution {
    public int longestChain(int[] values, int step) {
        long[] s = Arrays.stream(values).asLongStream().sorted().distinct().toArray();
        int[] length = new int[s.length];
        int best = 0;
        for (int i = 0; i < s.length; i++) {
            int j = Arrays.binarySearch(s, 0, i, s[i] - step);
            length[i] = j >= 0 ? length[j] + 1 : 1;
            best = Math.max(best, length[i]);
        }
        return best;
    }
}

