static int cmpLong(const void* x, const void* y) {
    long long p = *(const long long*) x, q = *(const long long*) y;
    return (p > q) - (p < q);
}

int longestChain(int* values, int valuesSize, int step) {
    long long* s = malloc(valuesSize * sizeof(long long));
    for (int i = 0; i < valuesSize; i++) s[i] = values[i];
    qsort(s, valuesSize, sizeof(long long), cmpLong);
    int m = 0;
    for (int i = 0; i < valuesSize; i++) if (m == 0 || s[i] != s[m - 1]) s[m++] = s[i];
    int* length = malloc(m * sizeof(int));
    int best = 0;
    for (int i = 0; i < m; i++) {
        long long want = s[i] - step;
        int lo = 0, hi = i;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (s[mid] < want) lo = mid + 1; else hi = mid;
        }
        length[i] = (lo < i && s[lo] == want) ? length[lo] + 1 : 1;
        if (length[i] > best) best = length[i];
    }
    free(s);
    free(length);
    return best;
}

