class Solution {
    public int longestChain(int[] values, int step) {
        Set<Long> have = new HashSet<>();
        for (int v : values) have.add((long) v);
        int best = 0;
        for (long v : have) {
            if (have.contains(v - step)) continue;
            int length = 1;
            long x = v;
            while (have.contains(x + step)) {
                x += step;
                length++;
            }
            best = Math.max(best, length);
        }
        return best;
    }
}

