// C has no built-in hash set, so here is a small one: open addressing with
// linear probing over a power-of-two table. Keys are 64-bit.
typedef struct { long long key; bool used; } Slot;

static unsigned slotOf(long long key, unsigned mask) {
    unsigned long long h = (unsigned long long) key * 0x9E3779B97F4A7C15ULL;
    return (unsigned) (h >> 32) & mask;
}

static bool has(const Slot* t, unsigned mask, long long key) {
    for (unsigned s = slotOf(key, mask); t[s].used; s = (s + 1) & mask)
        if (t[s].key == key) return true;
    return false;
}

static void add(Slot* t, unsigned mask, long long key) {
    unsigned s = slotOf(key, mask);
    while (t[s].used && t[s].key != key) s = (s + 1) & mask;
    t[s].key = key;
    t[s].used = true;
}

int longestChain(int* values, int valuesSize, int step) {
    unsigned cap = 1;
    while (cap < 2u * valuesSize) cap <<= 1;
    Slot* have = calloc(cap, sizeof(Slot));
    for (int i = 0; i < valuesSize; i++) add(have, cap - 1, values[i]);
    int best = 0;
    for (unsigned s = 0; s < cap; s++) {
        if (!have[s].used) continue;
        long long v = have[s].key;
        if (has(have, cap - 1, v - step)) continue;
        int length = 1;
        long long x = v;
        while (has(have, cap - 1, x + step)) {
            x += step;
            length++;
        }
        if (length > best) best = length;
    }
    free(have);
    return best;
}
